import json
import os
from pathlib import Path
import pytest
from bench_app.app import run

ROOT = Path(os.environ["BENCH_PROJECT_ROOT"]) if "BENCH_PROJECT_ROOT" in os.environ else Path(__file__).resolve().parents[1]

def test_policy_outside_checkout():
    request = json.loads("{\"operation\": \"policy\"}")
    expected = json.loads("{\"title\": \"Build ledger\", \"schema\": 2}")
    assert run(request, ROOT) == expected


def test_html_single_quotes():
    request = json.loads("{\"text\": \"'\\u96ea'\"}")
    expected = json.loads("{\"html\": \"<h1>Build ledger</h1><p>&#x27;\\u96ea&#x27;</p>\"}")
    assert run(request, ROOT) == expected


def test_manifest_order_unicode():
    request = json.loads("{\"operation\": \"manifest\", \"files\": {\"\\u96ea\": \"\\u00e9\", \"z\": \"\"}}")
    expected = json.loads("{\"sha256\": \"6ce01b6cd79d8f7e816179e984211dcf60d14622a607e226a55055d4aa26f005\"}")
    assert run(request, ROOT) == expected


def test_archive_time_not_request():
    request = json.loads("{\"operation\": \"archive\", \"files\": {\"x\": \"\"}, \"built_at\": [2030, 12, 31, 23, 59, 58]}")
    expected = json.loads("{\"members\": [{\"name\": \"x\", \"timestamp\": [2024, 1, 1, 0, 0, 0]}]}")
    assert run(request, ROOT) == expected


def test_csv_empty_and_crlf():
    request = json.loads("{\"operation\": \"csv\", \"rows\": [[\"\", \"a\\r\\nb\", \"\\u96ea\"]]}")
    expected = json.loads("{\"csv\": \",\\\"a\\r\\nb\\\",\\u96ea\\r\\n\"}")
    assert run(request, ROOT) == expected


def test_fractional_duration():
    request = json.loads("{\"operation\": \"duration\", \"value\": \"PT2M0.125S\"}")
    expected = json.loads("{\"milliseconds\": 120125}")
    assert run(request, ROOT) == expected


def test_zero_duration():
    request = json.loads("{\"operation\": \"duration\", \"value\": \"PT0S\"}")
    expected = json.loads("{\"milliseconds\": 0}")
    assert run(request, ROOT) == expected


def test_duration_days_rejected():
    request = json.loads("{\"operation\": \"duration\", \"value\": \"P1D\"}")
    with pytest.raises(ValueError, match='unsupported ISO duration'):
        run(request, ROOT)


def test_nfc_not_casefold():
    request = json.loads("{\"operation\": \"groups\", \"rows\": [{\"name\": \"A\", \"count\": 1}, {\"name\": \"a\", \"count\": 2}]}")
    expected = json.loads("{\"groups\": {\"A\": 1, \"a\": 2}}")
    assert run(request, ROOT) == expected


def test_weights_not_sample_count():
    request = json.loads("{\"operation\": \"weighted\", \"rows\": [{\"count\": 3, \"mean_ms\": 1}, {\"count\": 1, \"mean_ms\": 2}]}")
    expected = json.loads("{\"mean_ms\": \"1.250\"}")
    assert run(request, ROOT) == expected


def test_semantic_prerelease():
    request = json.loads("{\"operation\": \"releases\", \"versions\": [\"2.0.0\", \"2.0.0-rc.10\", \"2.0.0-rc.2\", \"2.0.0-alpha\", \"2.0.0-1\"]}")
    expected = json.loads("{\"versions\": [\"2.0.0-1\", \"2.0.0-alpha\", \"2.0.0-rc.2\", \"2.0.0-rc.10\", \"2.0.0\"]}")
    assert run(request, ROOT) == expected


def test_digest_preserves_newlines():
    request = json.loads("{\"operation\": \"digest\", \"base64\": \"YQ0KYgo=\"}")
    expected = json.loads("{\"sha256\": \"953bba9ac9726eaea07e844abcf144a0afe998039257c7a88b6665819597f39d\"}")
    assert run(request, ROOT) == expected


def test_tar_windows_parent():
    request = json.loads("{\"operation\": \"tar\", \"base64\": \"\"}")
    with pytest.raises(ValueError, match='unsafe archive path'):
        run(request, ROOT)


def test_tar_windows_drive():
    request = json.loads("{\"operation\": \"tar\", \"base64\": \"\"}")
    with pytest.raises(ValueError, match='unsafe archive path'):
        run(request, ROOT)


def test_tar_duplicate_backslash():
    request = json.loads("{\"operation\": \"tar\", \"base64\": \"\"}")
    with pytest.raises(ValueError, match='duplicate archive member'):
        run(request, ROOT)


def test_tar_exact_duplicate():
    request = json.loads("{\"operation\": \"tar\", \"base64\": \"\"}")
    with pytest.raises(ValueError, match='duplicate archive member'):
        run(request, ROOT)
